                <div class="d-flex align-center mb-3">
                  <v-icon small color="grey" class="mr-2">mdi-calendar</v-icon>
                  <span class="caption grey--text">
                    {{ formatDate(hodReview.date) }}
                  </span>
                </div>
                <div v-if="hodReview.comments" class="review-comment">
                  <v-icon small color="deep-purple" class="mr-2"
                    >mdi-message-text</v-icon
                  >
                  <span class="body-2">{{ hodReview.comments }}</span>
                </div>
              </v-card-text>
              <v-card-text v-else class="pa-4 text-center grey--text">
                <v-icon color="grey lighten-1">mdi-clock-outline</v-icon>
                <div class="caption mt-1">Awaiting HOD review</div>
              </v-card-text>
            </v-card>
          </div>

          <!-- HR Review -->
          <div
            class="timeline-item"
            :class="{ 'timeline-active': hrReview.status }"
          >
            <div class="timeline-marker">
              <v-avatar
                :color="hrReview.status ? 'blue' : 'grey lighten-2'"
                size="48"
                class="elevation-3"
              >
                <v-icon :color="hrReview.status ? 'white' : 'grey'">
                  mdi-account-group
                </v-icon>
              </v-avatar>
            </div>
            <v-card
              class="timeline-card elevation-4"
              :class="{ 'card-completed': hrReview.status }"
            >
              <v-card-title
                class="py-3 px-4"
                :class="hrReview.status ? 'blue lighten-5' : 'grey lighten-4'"
              >
                <div class="d-flex align-center justify-space-between w-100">
                  <span class="font-weight-bold">HR Review</span>
                  <v-chip
                    v-if="hrReview.status"
                    :color="getReviewStatusColor(hrReview.status.code)"
                    dark
                    small
                    class="elevation-2"
                  >
                    <v-icon left x-small>{{
                      getReviewIcon(hrReview.status.code)
                    }}</v-icon>
                    {{ hrReview.status.display }}
                  </v-chip>
                  <v-chip v-else color="grey" outlined small>
                    Pending
                  </v-chip>
                </div>
              </v-card-title>
              <v-card-text v-if="hrReview.status" class="pa-4">
                <div class="d-flex align-center mb-3">
                  <v-icon small color="grey" class="mr-2">mdi-calendar</v-icon>
                  <span class="caption grey--text">
                    {{ formatDate(hrReview.date) }}
                  </span>
                </div>
                <div v-if="hrReview.comments" class="review-comment">
                  <v-icon small color="blue" class="mr-2"
                    >mdi-message-text</v-icon
                  >
                  <span class="body-2">{{ hrReview.comments }}</span>
                </div>
              </v-card-text>
              <v-card-text v-else class="pa-4 text-center grey--text">
                <v-icon color="grey lighten-1">mdi-clock-outline</v-icon>
                <div class="caption mt-1">Awaiting HR review</div>
              </v-card-text>
            </v-card>
          </div>
        </div>
      </v-col>
    </v-row>

    <!-- Error State -->
    <v-row v-if="error && !loading">
      <v-col cols="12">
        <v-alert type="error" prominent>
          {{ error }}
        </v-alert>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
export default {
  name: "LeaveRequestView",
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,

      // Leave request data
      leaveData: {
        leaveCategory: "",
        leaveTypeId: "",
        startDate: "",
        endDate: "",
        returnDate: "",
        requestDate: "",
        cancelDate: "",
        days: 0,
        comments: "",
        status: "",
        statusDisplay: "",
      },

      // Practitioner
      practitionerId: "",
      practitionerName: "",

      // Acting supervisor
      actingSupervisorId: "",
      actingSupervisorName: "",

      // Supporting documents
      supportingDocuments: [],

      // Study leave data (if applicable)
      studyLeaveData: null,

      // Review statuses
      supervisorReview: {
        status: null,
        date: "",
        comments: "",
      },
      hodReview: {
        status: null,
        date: "",
        comments: "",
      },
      hrReview: {
        status: null,
        date: "",
        comments: "",
      },
    };
  },

  async created() {
    if (!this.queries.leave) {
      this.error = "No leave request ID provided";
      this.loading = false;
      return;
    }

    await this.loadLeaveRequest();
  },

  methods: {
    async loadLeaveRequest() {
      this.loading = true;
      this.error = null;

      try {
        // Fetch leave request and all related resources
        const url = `/fhir/Basic?_id=${this.queries.leave}&_revinclude=Basic:leaverequest`;
        const response = await fetch(url);

        if (!response.ok) {
          throw new Error("Failed to load leave request");
        }

        const bundle = await response.json();

        if (!bundle.entry || bundle.entry.length === 0) {
          throw new Error("Leave request not found");
        }

        // Extract resources
        const leaveRequest = bundle.entry.find(
          (e) => e.resource.id === this.queries.leave,
        )?.resource;

        if (!leaveRequest) {
          throw new Error("Leave request not found in response");
        }

        // Extract leave request data
        this.extractLeaveData(leaveRequest);

        // Load related data
        await this.loadPractitioner();
        await this.loadActingSupervisor();
        await this.loadLeaveCategory(leaveRequest);

        // Process all included resources for reviews and study leave
        for (const entry of bundle.entry) {
          const resource = entry.resource;

          // Check for supervisor review
          if (
            resource.meta?.profile?.includes(
              "http://ihris.org/fhir/StructureDefinition/supervisor-leave-approval-profile",
            )
          ) {
            this.extractSupervisorReview(resource);
          }

          // Check for HOD review
          if (
            resource.meta?.profile?.includes(
              "http://ihris.org/fhir/StructureDefinition/hod-leave-approval-profile",
            )
          ) {
            this.extractHODReview(resource);
          }

          // Check for HR review
          if (
            resource.meta?.profile?.includes(
              "http://ihris.org/fhir/StructureDefinition/hr-leave-approval-profile",
            )
          ) {
            this.extractHRReview(resource);
          }

          // Check for study leave details
          if (
            resource.meta?.profile?.includes(
              "http://ihris.org/fhir/StructureDefinition/study-leave-profile",
            )
          ) {
            await this.extractStudyLeaveData(resource);
          }
        }
      } catch (error) {
        console.error("Error loading leave request:", error);
        this.error = error.message || "Failed to load leave request";
      } finally {
        this.loading = false;
      }
    },

    extractLeaveData(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.leaveData.startDate = getExt("start-date", "valueDate");
      this.leaveData.endDate = getExt("end-date", "valueDate");
      this.leaveData.returnDate = getExt("return-date", "valueDate");
      this.leaveData.requestDate = getExt("request-date", "valueDate");
      this.leaveData.cancelDate = getExt("cancel-date", "valueDate");
      this.leaveData.days = getExt("days", "valueInteger") || 0;
      this.leaveData.comments = getExt("comments", "valueString") || "";

      // Status
      const statusCoding = getExt("status", "valueCoding");
      this.leaveData.status = statusCoding?.code || "";
      this.leaveData.statusDisplay = statusCoding?.display || "";

      // Supporting documents
      const docs = resource.extension?.filter((e) =>
        e.url.includes("supporting-document"),
      );
      this.supportingDocuments = docs?.map((d) => d.valueAttachment) || [];

      // Practitioner ID
      const practExt = resource.extension?.find((e) =>
        e.url.includes("practitioner"),
      );
      this.practitionerId =
        practExt?.valueReference?.reference?.split("/")[1] || "";

      // Acting supervisor ID
      const actingExt = resource.extension?.find((e) =>
        e.url.includes("acting-supervisor"),
      );
      this.actingSupervisorId =
        actingExt?.valueReference?.reference?.split("/")[1] || "";
    },

    async loadPractitioner() {
      if (!this.practitionerId) return;

      try {
        const response = await fetch(
          `/fhir/Practitioner/${this.practitionerId}`,
        );
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.practitionerName = name
          ? `${name.given?.join(" ")} ${name.family}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this.practitionerName = "Unknown";
      }
    },

    async loadActingSupervisor() {
      if (!this.actingSupervisorId) return;

      try {
        const response = await fetch(
          `/fhir/Practitioner/${this.actingSupervisorId}`,
        );
        const supervisor = await response.json();
        const name = supervisor.name?.[0];
        this.actingSupervisorName = name
          ? `${name.given?.join(" ")} ${name.family}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading acting supervisor:", error);
      }
    },

    async loadLeaveCategory(resource) {
      const catExt = resource.extension?.find((e) =>
        e.url.includes("leave-category"),
      );
      const categoryId = catExt?.valueReference?.reference?.split("/")[1];

      if (!categoryId) return;

      try {
        const response = await fetch(`/fhir/Basic/${categoryId}`);
        const category = await response.json();

        this.leaveData.leaveTypeId = categoryId;

        const nameExt = category.extension?.find((e) =>
          e.url.includes("ihris-basic-name"),
        );
        this.leaveData.leaveCategory = nameExt?.valueString || "Unknown";
      } catch (error) {
        console.error("Error loading leave category:", error);
      }
    },

    extractSupervisorReview(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.supervisorReview.status = getExt("review-status", "valueCoding");
      this.supervisorReview.date = getExt("action-date", "valueDate");
      this.supervisorReview.comments = getExt("description", "valueString");
    },

    extractHODReview(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.hodReview.status = getExt("review-status", "valueCoding");
      this.hodReview.date = getExt("action-date", "valueDate");
      this.hodReview.comments = getExt("description", "valueString");
    },

    extractHRReview(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.hrReview.status = getExt("review-status", "valueCoding");
      this.hrReview.date = getExt("action-date", "valueDate");
      this.hrReview.comments = getExt("description", "valueString");
    },

    async extractStudyLeaveData(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.studyLeaveData = {
        institution: getExt("planning-institution", "valueString"),
        course:
          getExt("planning-course", "valueString") ||
          (await this.resolveQualificationName(resource)),
        qualificationLevel: getExt("qualification-level", "valueCoding")
          ?.display,
        country: getExt("country", "valueCoding")?.display,
        trainingLocation: getExt("training-location", "valueString"),
        trainingType: getExt("training-type", "valueCoding")?.code,
        trainingTypeDisplay: getExt("training-type", "valueCoding")?.display,
        trainingPlan: null,
        trainingRecommendation: null,
      };

      // Store references for potential loading
      const planRef = getExt("training-plan-reference", "valueReference");
      const recoRef = getExt(
        "training-recommendation-reference",
        "valueReference",
      );

      if (planRef) {
        this.studyLeaveData.trainingPlan = {
          reference: planRef.reference,
          course: this.studyLeaveData.course,
          institution: this.studyLeaveData.institution,
        };
        await this.loadTrainingPlanDetails(planRef.reference);
      }

      if (recoRef) {
        this.studyLeaveData.trainingRecommendation = {
          reference: recoRef.reference,
          title: this.studyLeaveData.course,
        };
        await this.loadTrainingRecommendationDetails(recoRef.reference);
      }
    },

    async resolveQualificationName(resource) {
      const qualNameOtherExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name-other"),
      );
      if (qualNameOtherExt?.valueString) return qualNameOtherExt.valueString;

      const qualNameExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name"),
      );
      if (qualNameExt?.valueReference?.display) {
        return qualNameExt.valueReference.display;
      }

      const ref = qualNameExt?.valueReference?.reference;
      if (!ref) return null;

      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) return null;

        const qualification = await response.json();
        return qualification.extension?.find((e) =>
          e.url.endsWith("/ihris-basic-name"),
        )?.valueString;
      } catch (error) {
        console.error("Error resolving qualification name:", error);
        return null;
      }
    },

    async loadTrainingPlanDetails(reference) {
      try {
        const planId = reference.split("/")[1];
        const response = await fetch(`/fhir/Basic/${planId}`);
        if (!response.ok) return;

        const plan = await response.json();
        const getExt = (url, type) => {
          const ext = plan.extension?.find((e) => e.url.includes(url));
          return ext ? ext[type] : null;
        };

        this.studyLeaveData.trainingPlan = {
          ...this.studyLeaveData.trainingPlan,
          course:
            getExt("planning-course", "valueString") ||
            (await this.resolveQualificationName(plan)) ||
            this.studyLeaveData.trainingPlan.course,
          institution:
            getExt("planning-institution", "valueString") ||
            this.studyLeaveData.trainingPlan.institution,
          typeDisplay: getExt("training-type", "valueCoding")?.display,
          qualificationLevel: getExt("qualification-level", "valueCoding")
            ?.display,
          methodology: getExt("learning-methodology", "valueCoding")?.display,
          startDate: getExt("start-date", "valueDate"),
          endDate: getExt("end-date", "valueDate"),
          status: getExt("request-status", "valueCoding")?.code,
          statusDisplay: getExt("request-status", "valueCoding")?.display,
        };
      } catch (error) {
        console.error("Error loading training plan details:", error);
      }
    },

    async loadTrainingRecommendationDetails(reference) {
      try {
        const recoId = reference.split("/")[1];
        const response = await fetch(`/fhir/Basic/${recoId}`);
        if (!response.ok) return;

        const reco = await response.json();
        const getExt = (url, type) => {
          const ext = reco.extension?.find((e) => e.url.includes(url));
          return ext ? ext[type] : null;
        };

        this.studyLeaveData.trainingRecommendation = {
          ...this.studyLeaveData.trainingRecommendation,
          title:
            getExt("ihris-basic-name", "valueString") ||
            this.studyLeaveData.trainingRecommendation.title,
          description: getExt("description", "valueString"),
          typeDisplay: getExt("training-type", "valueCoding")?.display,
          startDate: getExt("start-date", "valueDate"),
          endDate: getExt("end-date", "valueDate"),
          fiscalYear: getExt("fiscal-year", "valueString"),
          totalParticipants: getExt("total-participants", "valueInteger"),
          institution: getExt("planning-institution", "valueString"),
          qualificationLevel: getExt("qualification-level", "valueCoding")
            ?.display,
          country: getExt("country", "valueCoding")?.display,
          trainingLocation: getExt("training-location", "valueString"),
          methodology: getExt("learning-methodology", "valueCoding")?.display,
        };
      } catch (error) {
        console.error("Error loading training recommendation details:", error);
      }
    },

    getLeaveTypeColor(leaveTypeId) {
      const typeMap = {
        annual: "blue",
        maternity: "pink",
        paternity: "indigo",
        compassionate: "purple",
        unpaid: "orange",
        sick: "red",
        stillborn: "deep-purple",
        bonding: "teal",
        study: "green",
      };
      return typeMap[leaveTypeId] || "grey";
    },

    getTrainingTypeColor() {
      const colorMap = {
        parttime: "blue",
        shortterm: "orange",
        longterm: "purple",
      };
      return colorMap[this.studyLeaveData?.trainingType] || "green";
    },

    getStatusColor(status) {
      const statusMap = {
        draft: "grey",
        undersupervisorreview: "orange",
        underhodreview: "deep-purple",
        underhrreview: "blue",
        approved: "success",
        rejected: "error",
        cancelled: "error",
      };
      return statusMap[status] || "grey";
    },

    getStatusIcon(status) {
      const iconMap = {
        draft: "mdi-file-document-edit",
        undersupervisorreview: "mdi-account-tie",
        underhodreview: "mdi-account-star",
        underhrreview: "mdi-account-group",
        approved: "mdi-check-circle",
        rejected: "mdi-close-circle",
      };
      return iconMap[status] || "mdi-help-circle";
    },

    getReviewStatusColor(status) {
      const statusMap = {
        approved: "success",
        rejected: "error",
      };
      return statusMap[status] || "grey";
    },

    getPlanStatusColor(status) {
      const colorMap = {
        draft: "grey",
        undersupervisorreview: "orange",
        approved: "success",
        rejected: "error",
      };
      return colorMap[status] || "grey";
    },

    getReviewIcon(status) {
      const iconMap = {
        approved: "mdi-check-circle",
        rejected: "mdi-close-circle",
      };
      return iconMap[status] || "mdi-help-circle";
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    downloadDocument(doc) {
      if (doc.data && doc.contentType) {
        const blob = this.base64toBlob(doc.data, doc.contentType);
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = doc.title || "document";
        link.click();
        window.URL.revokeObjectURL(url);
      }
    },

    base64toBlob(base64Data, contentType) {
      contentType = contentType || "";
      const sliceSize = 1024;
      const byteCharacters = atob(base64Data);
      const bytesLength = byteCharacters.length;
      const slicesCount = Math.ceil(bytesLength / sliceSize);
      const byteArrays = new Array(slicesCount);

      for (let sliceIndex = 0; sliceIndex < slicesCount; ++sliceIndex) {
        const begin = sliceIndex * sliceSize;
        const end = Math.min(begin + sliceSize, bytesLength);

        const bytes = new Array(end - begin);
        for (let offset = begin, i = 0; offset < end; ++i, ++offset) {
          bytes[i] = byteCharacters[offset].charCodeAt(0);
        }
        byteArrays[sliceIndex] = new Uint8Array(bytes);
      }
      return new Blob(byteArrays, { type: contentType });
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },
  },
};
</script>

